// n8n Code node: Run Once for All Items. No modules or network requests.
// Monetary inputs remain strings until converted to integer cents (BigInt).
// A percentage has at most four decimal places. Round HALF UP only at output.
const SCALE = 1000000n; // 100 percent * 10,000 fractional units per percent.
const CONFIRMATION = 'I checked eligibility and current merchant terms';
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[c]));
const normalized = (value) => String(value).toLowerCase().replace(/['’]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

function money(value, label, allowNone = false) {
  const text = typeof value === 'string' ? value.trim() : '';
  if (allowNone && text.toLowerCase() === 'none') return null;
  if (!/^(?:0|[1-9]\d{0,8})(?:\.\d{1,2})?$/.test(text)) {
    throw new Error(`${label}: enter a non-negative amount with at most two decimals, no commas or currency symbol${allowNone ? ', or none only if this limit is confirmed not applicable' : ''}.`);
  }
  const [whole, fractional = ''] = text.split('.');
  return BigInt(whole) * 100n + BigInt(fractional.padEnd(2, '0'));
}

function percent(value) {
  const text = typeof value === 'string' ? value.trim() : '';
  if (!/^\d{1,3}(?:\.\d{1,4})?$/.test(text)) {
    throw new Error('Discount percentage: enter 0 through 100, with at most four decimal places.');
  }
  const [whole, fractional = ''] = text.split('.');
  const scaled = BigInt(whole) * 10000n + BigInt(fractional.padEnd(4, '0'));
  if (scaled > SCALE) throw new Error('Discount percentage must be 0 through 100.');
  return { scaled, text };
}

function format(cents) {
  return `${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
}

return $input.all().map((item, index) => {
  try {
    const input = $('Configure currency and heading').all()[index]?.json;
    if (!input) throw new Error('The original form input was not available. Run the complete workflow from its form.');
    if (input.terms_confirmation !== CONFIRMATION) {
      throw new Error('Check your eligibility, exclusions and current merchant terms before calculating. Unknown limits must not be treated as none.');
    }
    const brandQuery = String(input.brand_query || '').trim();
    if (!brandQuery || brandQuery.length > 120 || !normalized(brandQuery)) {
      throw new Error('Enter a brand name of at most 120 characters for the guide lookup.');
    }
    const response = item.json;
    const apiBody = response?.body;
    const apiStatus = response?.statusCode;
    const candidates = apiStatus === 200 && Array.isArray(apiBody?.items) ? apiBody.items : [];
    const sought = normalized(brandQuery);
    const guide = candidates.find((candidate) =>
      normalized(candidate.id || '').includes(sought) || normalized(candidate.title || '').includes(sought)
    );
    const safeGuideUrl = guide && /^https:\/\/salutescout\.com\/[a-z0-9-]+\/$/.test(String(guide.source_url || ''))
      ? guide.source_url : null;
    const lookupStatus = apiStatus !== 200 ? 'lookup_unavailable'
      : safeGuideUrl ? 'direct_guide_match' : 'no_direct_guide_match';
    const lookupMessage = lookupStatus === 'direct_guide_match'
      ? `<p>Matching published guide: <a href="${escapeHtml(safeGuideUrl)}">${escapeHtml(guide.title)}</a>. Site review date: ${escapeHtml(guide.last_modified || 'not stated')}. ${escapeHtml(guide.summary || '')}</p><p>This is published site content, not fresh merchant verification. Check the linked guide and current merchant terms before checkout.</p>`
      : lookupStatus === 'no_direct_guide_match'
        ? `<p>No directly matching guide was found in the currently indexed SaluteScout API results for “${escapeHtml(brandQuery)}”. This does not establish whether a merchant offers a discount. The API index may lag behind the site.</p>`
        : `<p>Guide lookup was unavailable (API status ${escapeHtml(apiStatus ?? 'unknown')}). The basket arithmetic below uses only the terms you entered; check current merchant terms separately.</p>`;
    const currency = String(input.currency_code || 'USD');
    if (!/^[A-Z]{3}$/.test(currency)) throw new Error('Set currency_code to a three-letter currency label. No currency conversion is performed.');
    const eligible = money(input.eligible_subtotal, 'Eligible goods subtotal');
    const excluded = money(input.excluded_subtotal, 'Excluded goods subtotal');
    const rate = percent(input.discount_percent);
    const ceiling = money(input.eligible_spend_ceiling, 'Eligible-spend ceiling', true);
    const remaining = money(input.remaining_discount_allowance, 'Remaining discount allowance', true);
    const base = ceiling === null || eligible <= ceiling ? eligible : ceiling;
    let numerator = base * rate.scaled;
    if (remaining !== null && numerator > remaining * SCALE) numerator = remaining * SCALE;
    const discount = (numerator + SCALE / 2n) / SCALE;
    const total = eligible + excluded - discount;
    const values = {
      currency,
      eligible_subtotal: format(eligible),
      excluded_subtotal: format(excluded),
      discount_base: format(base),
      discount_percent: rate.text,
      eligible_spend_ceiling: ceiling === null ? 'confirmed not applicable' : format(ceiling),
      remaining_discount_allowance: remaining === null ? 'confirmed not applicable' : format(remaining),
      goods_subtotal: format(eligible + excluded),
      estimated_discount: format(discount),
      estimated_goods_total: format(total),
    };
    const rows = [
      ['Eligible goods', values.eligible_subtotal],
      ['Excluded goods', values.excluded_subtotal],
      ['Discount base after eligible-spend ceiling', values.discount_base],
      ['Goods before discount', values.goods_subtotal],
      ['Estimated discount', values.estimated_discount],
      ['Estimated goods total after discount', values.estimated_goods_total],
    ].map(([label, value]) => `<tr><td>${label}</td><td>${currency} ${value}</td></tr>`).join('');
    const resultHtml = `${lookupMessage}<p>${escapeHtml(input.result_label || 'Pre-tax basket estimate')}</p><table>${rows}</table>`
      + `<p>Entered rate: ${escapeHtml(rate.text)}%. Eligible-spend ceiling: ${escapeHtml(values.eligible_spend_ceiling)}. Remaining discount allowance: ${escapeHtml(values.remaining_discount_allowance)}.</p>`
      + '<p>Formula: min(min(eligible subtotal, eligible-spend ceiling) x percentage / 100, remaining discount allowance). A limit confirmed not applicable is unbounded. Round the discount to cents using half-up rounding, then subtract it from eligible plus excluded goods.</p>'
      + '<p>Before checkout, confirm:</p><ul><li>Your purchaser status and required verification qualify.</li><li>The goods and purchase route are eligible.</li><li>The rate, purchase ceiling and remaining allowance are current.</li><li>Minimum spend, stacking, taxes, shipping and merchant rounding are checked separately.</li></ul>'
      + '<p>This estimates arithmetic only. It does not establish eligibility or promise a merchant discount. All amounts must use the same currency, with two decimal minor units. No current retailer rates are built in.</p>';
    return { json: { valid: true, ...values, brand_query: brandQuery, lookup_status: lookupStatus,
      guide_source_url: safeGuideUrl, guide_last_modified: safeGuideUrl ? guide.last_modified : null,
      title: 'Your basket estimate and guide lookup', result_html: resultHtml }, pairedItem: { item: index } };
  } catch (error) {
    return { json: { valid: false, title: 'Check the inputs before calculating', error: error.message,
      result_html: `<p>${escapeHtml(error.message)}</p><p>Return to the form and correct the input. Do not guess an unknown eligibility rule or limit.</p>` }, pairedItem: { item: index } };
  }
});
